def process(fp):
    with open(fp, "r", encoding="utf-8") as f:
        d = json.load(f)
    for cat in d["categories"]:
        if cat.get("id") == "xray_scan":
            for sub in cat["subcategories"]:
                if sub["id"] == "medical_anatomy_male":
                    # Avoid duplicate
                    ids = [t["id"] for t in sub["templates"]]
                    if "med_male_specific" in ids:
                        print("  already present in", fp)
                        continue
                    sub["templates"].append(MALE_TPL)
                    # update sub description to mention 7 templates
                    sub["description"] = sub["description"].replace("6 \u4e2a\u6a21\u677f", "7 \u4e2a\u6a21\u677f")
                    print("  appended MALE_TPL to", fp)
                if sub["id"] == "medical_anatomy_female":
                    ids = [t["id"] for t in sub["templates"]]
                    if "med_female_specific" in ids:
                        print("  already present in", fp)
                        continue
                    sub["templates"].append(FEMALE_TPL)
                    sub["description"] = sub["description"].replace("6 \u4e2a\u6a21\u677f", "7 \u4e2a\u6a21\u677f")
                    print("  appended FEMALE_TPL to", fp)
    with open(fp, "w", encoding="utf-8") as f:
        json.dump(d, f, ensure_ascii=False, indent=2)
    print("saved", fp)


if __name__ == "__main__":
    for p in [
        r"C:\BSAI\ComfyUI-BSAI_pro_v39\ComfyUI\custom_nodes\BSAI-MiniMAX-H3-Prompt\templates\prompt_templates.json",
        r"C:\BSAI\ComfyUI-BSAI_pro_v39\ComfyUI\custom_nodes\BSAI-MiniMAX-H3-Prompt\web\templates_data.json",
    ]:
        process(p)
